float calculate_drift(uint32_t *accumulator, uint32_t frames)
{
    *accumulator += frames;
    // Only updated once per 1024 samples, wraps around after 1024 elements
    // -> gives period of ~22 seconds
    const uint32_t idx0 = (*accumulator >> 10) & 0x3FF;
    const uint32_t idx1 = (idx0 + 1) & 0x3FF;

    const float d0 = drift_tbl[idx0];
    const float d1 = drift_tbl[idx1];

    const float ratio = (*accumulator & 0x3FF) / (float)0x400;

    return d0 + (d1 - d0) * ratio;
}
